// 真正原报价→Action→begin与只读前界配对；不构造永久运输或商铺资格。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_departure_source.hpp"
namespace {
// 地形沿原planner；原货批只经真实AddLot准备，不手填起行结果。
void prepare_departure_map(Fixture& f,bool terrain_mode){
 if(terrain_mode){terrain::TerrainMap map;map.id="map";map.width=40;map.height=20;map.cell_size=20;map.cells.resize(2);map.budgets={{terrain::Mode::foot,10},{terrain::Mode::army,10},{terrain::Mode::boat,10}};map.money_per_tick=7;map.fatigue_per_tick=2;require(terrain::validate_map(map).ok,"original terrain map");f.catalog.world_map_id=map.id;f.catalog.maps.insert(map.id,map);f.catalog.settlements.find("A")->map_xy={10,10};f.catalog.settlements.find("B")->map_xy={30,10};}
 f.common_catalog->items.insert("grain",{"grain",1,1});require(f.common.apply_resources({{AddLot{"bag.carrier","grain",2,{Owner::Kind::actor,"carrier",{}},{}},AddLot{"bag.carrier","grain",3,{Owner::Kind::actor,"carrier",{}},{}}},{}}).ok,"actual original personal lots");
}
// 原开始前真实分配一次行动并占用本人，不先安装任何Travel载荷。
StableId install_departure_action(Fixture& f,const TravelQuote& quote){auto id=f.common.next_id("action");require(id.ok,"actual departure action ID");ActionMutation m;m.kind=ActionMutation::Kind::insert;m.action={id.value,"travel","carrier",{"carrier"},f.common.tick(),quote.duration};require(f.common.apply_action(m).ok,"original departure action");ActorMutation a;a.actor_id="carrier";a.action_id=id.value;require(f.common.apply_actor(a).ok,"original departure actor occupied");return id.value;}
// 道路与地形均无预付；原物品、钱包、Action和真实计划头逐项不能替换。
void original_departure(bool terrain_mode){Fixture f;prepare_departure_map(f,terrain_mode);TravelCommand command;command.destination=StableId{"B"};auto q=plan_travel(f.common,f.travel,f.catalog,f.services,"carrier",command.destination);require(q.ok,"original departure quote");auto id=install_departure_action(f,q.value);std::vector<StableId> lots;for(const auto& lot:f.common.inventory("bag.carrier")->lots)lots.push_back(lot.id);
 check(!capture_private_shop_travel_departure_boundary(f.common,f.travel,f.catalog,id,q.value,&command,lots).ok,"departure requires actual capture");require(f.common.begin_resource_execution_capture().ok,"start actual departure capture");auto boundary=capture_private_shop_travel_departure_boundary(f.common,f.travel,f.catalog,id,q.value,&command,lots);require(boundary.ok,"capture original uninstalled departure");auto no_boundary=PrivateShopTravelDepartureBoundary{};std::optional<TravelPlanInstallationDraft> draft;require(begin_travel(f.common,f.travel,f.catalog,id,q.value,&command,&draft).ok&&draft.has_value(),"actual original begin success");
 auto read=read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,*draft);require(read.ok,"read actual departure installation");check(read.value.original_selected_lots.size()==2&&read.value.actual_installation.after.terrain_plan.has_value()==terrain_mode,"actual selected lots and original plan source");check(f.funds("carrier")==100&&f.common.resource_execution_drafts().empty(),"original begin never prepays");check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,no_boundary,*draft).ok,"default boundary cannot invent start");check(!capture_private_shop_travel_departure_boundary(f.common,f.travel,f.catalog,id,q.value,&command,lots).ok,"installed journey cannot be recaptured as first departure");
 auto bad=*draft;bad.original_quote.cost++;check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,bad).ok,"different original quote rejected");bad=*draft;bad.before.location=SettlementLocation{"B","B.exit"};check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,bad).ok,"changed actual departure town rejected");bad=*draft;bad.after.action.participants.push_back("other");check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,bad).ok,"changed participant snapshot rejected");
 if(!terrain_mode){auto hidden=*draft;std::get<RoadTravelParams>(*hidden.after.params).met_actions.push_back("unserialized-contact");check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,hidden).ok,"hidden optional source value cannot change");}
 auto& bag=*f.common.state().inventories.find("bag.carrier");std::swap(bag.lots[0],bag.lots[1]);check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,*draft).ok,"same cargo reordered cannot pass departure");std::swap(bag.lots[0],bag.lots[1]);f.common.state().actors.find("carrier")->wallet_id="wallet.other";check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,*draft).ok,"actor payer link cannot change");f.common.state().actors.find("carrier")->wallet_id="wallet.carrier";
 require(f.common.apply_resources({{WalletDelta{"wallet.carrier",0,true}},{}}).ok,"actual zero payment recipe inserted");check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,*draft).ok,"even zero recipe cannot join first begin");require(f.common.finish_resource_execution_capture().ok,"end actual capture");require(f.common.begin_resource_execution_capture().ok,"restart same Common");check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,boundary.value,*draft).ok,"old boundary cannot consume restarted capture");}
// 原Common保存点及外层Travel保存集恢复后，旧成功安装草稿不可继续使用。
void aborted_departure(){Fixture f;prepare_departure_map(f,true);TravelCommand command;command.destination=StableId{"B"};auto q=plan_travel(f.common,f.travel,f.catalog,f.services,"carrier",command.destination);require(q.ok,"rollback actual quote");auto id=install_departure_action(f,q.value);const auto lot=f.common.inventory("bag.carrier")->lots[0].id;require(f.common.begin_resource_execution_capture().ok,"rollback actual capture");auto b=capture_private_shop_travel_departure_boundary(f.common,f.travel,f.catalog,id,q.value,&command,{lot});require(b.ok,"rollback actual boundary");auto save=f.common.begin_savepoint();require(save.ok,"original Common savepoint");const auto travel_before=f.travel;std::optional<TravelPlanInstallationDraft> draft;require(begin_travel(f.common,f.travel,f.catalog,id,q.value,&command,&draft).ok&&draft.has_value(),"actual installed terrain before abort");require(f.common.rollback_savepoint(save.value).ok,"rollback Common action location and head");f.travel=travel_before;check(!read_private_shop_travel_departure(f.common,f.travel,f.catalog,b.value,*draft).ok,"aborted original source rejected");}
}
int main(){try{original_departure(false);original_departure(true);aborted_departure();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_DEPARTURE_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
